 else if(r.method==='tools/call'&&r.params?.name==='list_rollout_issues'){log({event:'read',tool:r.params.name});result={content:[{type:'text',text:readFileSync(join(root,'issues.json'),'utf8')}]};}
 else if(r.method==='resources/list')result={resources:[]};
 else if(r.method==='resources/templates/list')result={resourceTemplates:[]};
 else if(r.method==='prompts/list')result={prompts:[]};
 else {process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:r.id,error:{code:-32601,message:'Unsupported fixture method'}})+'\n');continue;}
 process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:r.id,result})+'\n');
